import{_ as e,c as t,o as s,ah as p}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"題要","description":"周易集註 - 題要","frontmatter":{"title":"題要","description":"周易集註 - 題要"},"headers":[],"relativePath":"classics/jizhu/002.md","filePath":"classics/jizhu/002.md"}'),r={name:"classics/jizhu/002.md"};function i(c,a,_,o,n,l){return s(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="題要" tabindex="-1">題要 <a class="header-anchor" href="#題要" aria-label="Permalink to “題要”">​</a></h1><p>臣等謹案，《周易集註》十六卷，明來知德撰。知德，字矣鮮，梁山人，嘉靖壬子舉人。萬曆三十年，總督王象乾巡撫郭子章薦授翰林院待詔，知德以老疾辭詔，以所授官至任，事蹟具《明史儒林傳》。</p><p>知德自鄉舉之後，即移居萬縣深山中，精思易理。自隆慶庚午至萬曆戊戌，閱二十九年而成此書。其立說專取《繫辭》中錯綜其數以論易象，而以雜卦治之。</p><p>錯者，陰陽對錯，如先天圓圖：幹錯坤，坎錯離，八卦相錯是也。綜者，一上一下，如屯蒙之類，本是一卦，在下為屯，在上為蒙。載之文王序卦是也。</p><p>其論錯有四正錯，有四隅錯。論綜有四正綜。有四隅綜;有以正綜隅，有以隅綜正。其論象有卦情之象，有卦畫之象，有大象之象，有中爻之象，有錯卦之象，有綜卦之象，有爻變之象，有佔中之象。其注皆先釋象義、字義，及錯綜義，然後訓本卦本爻正義，皆由冥心力索，得其端倪，因而參互旁通，自成一說，當時推為絕學。</p><p>然上下經各十八卦，本稅與權之舊說。而所說中爻之象，亦即漢以來互體之法。特知德縱橫推闡，專明斯義，較先儒為詳盡耳。其自序乃高自位置，至謂孔子沒後而易亡，二千年有如長夜，豈非伏處村塾，不盡睹遺文秘籍之傳，不盡聞老師宿儒之論。師心自悟，偶有所得，遽夜郎自大哉。故百餘年來信其說者頗多，攻其說者亦不少。然易道淵深，包羅眾象。隨得一隙而入，皆能宛轉關通，有所闡發，亦不必盡以支離繁碎斥也。</p><p>乾隆四十六年九月恭校上</p><p>總纂官　臣 紀昀　臣 陸錫熊　臣 孫士毅</p><p>總校官　臣 陸費墀</p>',9)])])}const m=e(r,[["render",i]]);export{h as __pageData,m as default};
